T(78,1,"Мої цілі","Говорити про цілі зі словами going to.",
 "I'm going to + дієслово — план або намір: I'm going to learn English. Achieve — досягати, succeed — досягти успіху, success — успіх, progress — прогрес, step — крок. Приклад: I'm going to achieve my goal. Success takes time.",
 [W("achieve","/əˈtʃiːv/",V,"досягати","I'm going to achieve my goal.","Я досягну своєї мети."),
  W("succeed","/səkˈsiːd/",V,"досягти успіху","I want to succeed.","Я хочу досягти успіху."),
  W("success","/səkˈses/",N,"успіх","Success takes time.","Успіх вимагає часу."),
  W("progress","/ˈprəʊɡres/",N,"прогрес","I make progress every day.","Я роблю прогрес щодня."),
  W("step","/step/",N,"крок","This is the first step.","Це перший крок.")],
 ("What do you write at the top?","Повторимо. Привіт, Анно. Що написати?",["Dear Anna,","Dear to Anna,","To dear Anna,"],"Dear Anna,"),
 [("I'm going to achieve my goal.","Прослухайте. Що збирається зробити людина?",["Досягти мети","Змінити мету","Забути мету"],"Achieve."),
  ("Success takes time.","Прослухайте. Що вимагає часу?",["Успіх","Прогрес","Крок"],"Success."),
  ("This is the first step.","Прослухайте. Який це крок?",["Перший","Другий","Останній"],"First.")],
 [("I'm going to ___ my goal.",["achieve","success","step"],"Achieve."),
  ("I want to ___.",["succeed","success","progress"],"Succeed — дієслово."),
  ("I make ___ every day.",["progress","succeed","achieve"],"Progress.")],
 ("Що таке success?",["успіх","крок","мета"],"Success — успіх."),
 ("Я досягну своєї мети.",["I'm","going","to","achieve","my","goal"],["am","success"],"I'm going to achieve my goal."),
 ("Це перший крок.",["This is the first step"],"This is the first step."),
 ("What are you going to do?","Досягти мети. Що відповісти?",["I'm going to achieve my goal.","I going achieve my goal.","I'm go to achieve goal."],"I'm going to achieve my goal."))
